#!/usr/bin/env python3
"""Strict source-only tests for *verified* Flash Studio 1.7.9 A/B normalization."""
from __future__ import annotations
from pathlib import Path
import tempfile
import unittest

from flashforge_original_ad5x_ad5m_cli_qa import compare_original_gcode


def gcode(timestamp="2026-11-07 at 00:53:32",
          move="G1 X10.5 E2.0",
          end="\n",
          header=True):
    lines=["; HEADER_BLOCK_START",
           "; generated by Flash Studio 1.7.9 on "+timestamp,
           "; total layer number: 100",
           "; filament: 1",
           "; max_z_height: 20",
           "; more OEM config",
           "; one more config",
           "; HEADER_BLOCK_END" if header else "; HEADER_NO_END",
           "M104 S210",
           move,
           "M140 S0",
           "M84"]
    return (end.join(lines)+end).encode("utf-8")


class StrictFlashforgeABTest(unittest.TestCase):
    def compare(self,a,b):
        with tempfile.TemporaryDirectory() as d:
            root=Path(d)
            x=root/"a.gcode";y=root/"b.gcode"
            x.write_bytes(a);y.write_bytes(b)
            result=compare_original_gcode(x,y,root/"proof.json")
            self.assertTrue((root/"proof.json").is_file())
            return result

    def test_exact_bytes(self):
        r=self.compare(gcode(),gcode())
        self.assertEqual(r["result"],"PASS_RAW_IDENTICAL")

    def test_only_proven_header_timestamp(self):
        r=self.compare(gcode(),gcode(timestamp="2026-11-07 at 00:53:33"))
        self.assertEqual(r["result"],"PASS_ONLY_VERIFIED_HEADER_TIMESTAMP")
        self.assertEqual(r["changed_lines"],[2])
        self.assertIn("normalized_sha256",r)

    def test_other_brand_header_rejected(self):
        b=gcode(timestamp="2026-11-07 at 00:53:33").replace(
          b"Flash Studio 1.7.9",b"Flash Studio 1.8.0")
        r=self.compare(gcode(),b)
        self.assertEqual(r["result"],"FAIL_UNAUTHORIZED_GCODE_DIFFERENCE")

    def test_motion_difference_rejected(self):
        r=self.compare(gcode(),gcode(timestamp="2026-11-07 at 00:53:33",
                                     move="G1 X10.6 E2.0"))
        self.assertEqual(r["result"],"FAIL_UNAUTHORIZED_GCODE_DIFFERENCE")

    def test_missing_header_end_rejected(self):
        r=self.compare(gcode(header=False),gcode(timestamp="2026-11-07 at 00:53:33",header=False))
        self.assertEqual(r["result"],"FAIL_UNAUTHORIZED_GCODE_DIFFERENCE")

    def test_newline_mutation_rejected(self):
        r=self.compare(gcode(end="\n"),gcode(timestamp="2026-11-07 at 00:53:33",end="\r\n"))
        self.assertEqual(r["result"],"FAIL_UNAUTHORIZED_GCODE_DIFFERENCE")


if __name__=="__main__":
    unittest.main()
